  ('tempinbox.com'), ('discard.email'), ('burnermail.io'), ('1secmail.com'),
  ('moakt.com'), ('tempail.com')
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function private.email_hash(p_email text)
returns text
language sql
immutable
set search_path = ''
as $$
  select encode(extensions.digest(lower(trim(coalesce(p_email, ''))), 'sha256'), 'hex')
$$;

create or replace function private.is_email_blocked(p_email text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_email is not null and (
    exists (select 1 from private.blocked_emails b where b.email_hash = private.email_hash(p_email))
    or exists (
      select 1 from private.blocked_email_domains d
       where d.domain = lower(split_part(trim(p_email), '@', 2))
    )
  )
$$;

-- Operator helpers, for the SQL editor only (not callable through the API).
create or replace function private.block_email(p_email text, p_reason text default 'manual')
returns void
language sql
security definer
set search_path = ''
as $$
  insert into private.blocked_emails (email_hash, reason)
  values (private.email_hash(p_email), coalesce(p_reason, 'manual'))
  on conflict (email_hash) do nothing
$$;

create or replace function private.block_email_domain(p_domain text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into private.blocked_email_domains (domain) values (lower(trim(p_domain)))
  on conflict (domain) do nothing
$$;

create or replace function private.assert_username_allowed(p_username text)
returns void
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_username is null or p_username !~ '^[a-z0-9_]{3,24}$' then
    raise exception 'invalid username' using errcode = '22023';
  end if;
  if p_username in ('admin', 'administrator', 'bvm', 'help', 'moderator', 'official',
                    'root', 'security', 'staff', 'support', 'system') then
    raise exception 'this username is reserved' using errcode = '23505';
  end if;
end
$$;

create or replace function private.assert_not_suspended(p_uid uuid)
returns void
language plpgsql
stable
set search_path = ''
as $$
begin
  if exists (select 1 from public.users u where u.id = p_uid and u.suspended_at is not null) then
    raise exception 'this account is suspended' using errcode = 'BVM02';
  end if;
end
$$;

revoke all on function private.email_hash(text) from public, anon, authenticated;
revoke all on function private.is_email_blocked(text) from public, anon, authenticated;
revoke all on function private.block_email(text, text) from public, anon, authenticated;
revoke all on function private.block_email_domain(text) from public, anon, authenticated;
revoke all on function private.assert_username_allowed(text) from public, anon, authenticated;
revoke all on function private.assert_not_suspended(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Registration: blocked e-mail addresses and reserved usernames
-- ---------------------------------------------------------------------------
create or replace function public.create_account(
  p_username      text,
  p_phone         text,
  p_identity_key  text,
  p_signing_key   text,
  p_fallback_key  jsonb,
  p_one_time_keys jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if private.is_email_blocked((select au.email from auth.users au where au.id = v_uid)) then
    raise exception 'this e-mail address cannot be used' using errcode = 'BVM03';
  end if;
  perform private.assert_username_allowed(p_username);
  if p_phone is null or p_phone !~ '^\+[1-9][0-9]{6,14}$' then
    raise exception 'invalid phone number' using errcode = '22023';
  end if;
  perform private.assert_b64(p_identity_key, 40, 64);
  perform private.assert_b64(p_signing_key, 40, 64);

  insert into public.users (id, username, identity_key, signing_key, fallback_key)
  values (v_uid, p_username, p_identity_key, p_signing_key, private.clean_signed_key(p_fallback_key));

  insert into private.user_contact (user_id, phone_enc)
  values (v_uid, extensions.pgp_sym_encrypt(p_phone, private.contact_key(), 'cipher-algo=aes256'))
  on conflict (user_id) do update
    set phone_enc = excluded.phone_enc, phone_verified = false, updated_at = now();

  perform private.insert_one_time_keys(v_uid, p_one_time_keys);
end
$$;

-- Supabase Auth "Before User Created" hook (optional, recommended): refuses
-- sign-ups from blocked addresses and domains before any OTP e-mail is sent.
-- Enable under Authentication > Hooks > Before User Created > Postgres
-- function `public.bvm_before_user_created`.
create or replace function public.bvm_before_user_created(event jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if private.is_email_blocked(event->'user'->>'email') then
    return jsonb_build_object('error', jsonb_build_object(
      'message', 'This e-mail address cannot be used with BVM.',
      'http_code', 403
    ));
  end if;
  return '{}'::jsonb;
end
$$;
revoke all on function public.bvm_before_user_created(jsonb) from public, anon, authenticated;
grant execute on function public.bvm_before_user_created(jsonb) to supabase_auth_admin;

-- ---------------------------------------------------------------------------
-- Username change (at most once every 24 hours)
-- ---------------------------------------------------------------------------
create or replace function public.change_username(p_device_key text, p_username text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := auth.uid();
  v_current text;
  v_changed timestamptz;
begin
  perform private.assert_current_device(v_uid, p_device_key);
  perform private.assert_not_suspended(v_uid);
  perform private.assert_username_allowed(p_username);
  select u.username, u.username_changed_at into v_current, v_changed
    from public.users u where u.id = v_uid;
  if v_current = p_username then
    return;
  end if;
  if v_changed is not null and v_changed > now() - interval '24 hours' then
    raise exception 'the username can be changed once every 24 hours' using errcode = 'BVM04';
  end if;
  update public.users
     set username = p_username, username_changed_at = now()
   where id = v_uid;
end
$$;

-- Discovery skips suspended accounts.
create or replace function public.lookup_user(p_username text)
returns table (id uuid, username text, identity_key text, signing_key text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  return query
    select u.id, u.username, u.identity_key, u.signing_key
      from public.users u
     where u.username = lower(trim(p_username))
       and u.suspended_at is null;
end
$$;

-- Suspended accounts cannot start new sessions.
create or replace function public.claim_one_time_key(p_user_id uuid)
returns table (key_id text, public_key text, signature text, is_fallback boolean)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_row public.one_time_keys%rowtype;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_user_id = auth.uid() then
    raise exception 'cannot claim your own keys' using errcode = '22023';
  end if;
  perform private.assert_not_suspended(auth.uid());

  delete from public.one_time_keys k
   where k.id = (
     select k2.id from public.one_time_keys k2
      where k2.user_id = p_user_id
      order by k2.id
      limit 1
      for update skip locked
   )
  returning k.* into v_row;

  if v_row.id is not null then
    return query select v_row.key_id, v_row.public_key, v_row.signature, false;
    return;
  end if;

  return query
    select u.fallback_key->>'id', u.fallback_key->>'key', u.fallback_key->>'sig', true
      from public.users u
     where u.id = p_user_id and u.fallback_key is not null;
end
$$;

-- New phone: also forget the previous phone's inbox token.
create or replace function public.replace_device_keys(
  p_identity_key  text,
  p_signing_key   text,
  p_fallback_key  jsonb,
  p_one_time_keys jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform private.assert_b64(p_identity_key, 40, 64);
  perform private.assert_b64(p_signing_key, 40, 64);

  update public.users
     set identity_key = p_identity_key,
         signing_key = p_signing_key,
         fallback_key = private.clean_signed_key(p_fallback_key),
         keys_updated_at = now()
   where id = v_uid;
  if not found then
    raise exception 'no account for this user' using errcode = 'P0002';
  end if;

  delete from public.one_time_keys where user_id = v_uid;
  delete from public.relay where recipient_id = v_uid;
  delete from private.inbox_tokens where user_id = v_uid;
  perform private.insert_one_time_keys(v_uid, p_one_time_keys);
end
$$;

-- ---------------------------------------------------------------------------
-- Relay: blocked senders are dropped silently, suspended senders refused.
-- The sender cannot tell that it was blocked (the call succeeds either way).
-- ---------------------------------------------------------------------------
create or replace function public.relay_send(
  p_device_key text,
  p_id         uuid,
  p_recipient  uuid,
  p_type       text,
  p_ciphertext text,
  p_expires_at timestamptz default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  perform private.assert_not_suspended(v_uid);
  if p_id is null or p_recipient is null then
    raise exception 'missing id or recipient' using errcode = '22023';
  end if;
  if exists (select 1 from private.blocks b where b.blocker_id = p_recipient and b.blocked_id = v_uid) then
    return;
  end if;
  insert into public.relay (id, recipient_id, sender_id, type, ciphertext, expires_at)
  values (p_id, p_recipient, v_uid, p_type, p_ciphertext, p_expires_at)
  on conflict (id) do nothing;
end
$$;

-- ---------------------------------------------------------------------------
-- Blocking
-- ---------------------------------------------------------------------------
create or replace function public.block_user(p_device_key text, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  if p_user is null or p_user = v_uid then
    raise exception 'invalid user' using errcode = '22023';
  end if;
  insert into private.blocks (blocker_id, blocked_id)
  select v_uid, p_user where exists (select 1 from auth.users au where au.id = p_user)
  on conflict do nothing;
  -- Whatever they already queued for you is dropped too.
  delete from public.relay r where r.recipient_id = v_uid and r.sender_id = p_user;
end
$$;

create or replace function public.unblock_user(p_device_key text, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  delete from private.blocks b where b.blocker_id = v_uid and b.blocked_id = p_user;
end
$$;

-- Your block list (survives moving to a new phone).
create or replace function public.my_blocks()
returns table (user_id uuid, username text, blocked_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  return query
    select b.blocked_id, u.username, b.created_at
      from private.blocks b
      left join public.users u on u.id = b.blocked_id
     where b.blocker_id = auth.uid()
     order by b.created_at desc;
end
$$;

-- ---------------------------------------------------------------------------
-- Spam reports: report = block + report. An account reported by 5 different
-- users (whose own accounts are at least a day old) within 30 days is
-- suspended and its e-mail address is added to the blocklist (as a hash).
-- ---------------------------------------------------------------------------
create or replace function public.report_spam(p_device_key text, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := auth.uid();
  v_reports integer;
begin
  perform private.assert_current_device(v_uid, p_device_key);
  perform public.block_user(p_device_key, p_user);
  insert into private.spam_reports (reporter_id, reported_id)
  select v_uid, p_user where exists (select 1 from auth.users au where au.id = p_user)
  on conflict (reporter_id, reported_id) do update set created_at = now();

  select count(*) into v_reports
    from private.spam_reports s
    join public.users reporter on reporter.id = s.reporter_id
   where s.reported_id = p_user
     and s.created_at > now() - interval '30 days'
     and reporter.created_at < now() - interval '1 day';

  if v_reports >= 5 then
    update public.users set suspended_at = now()
     where id = p_user and suspended_at is null;
    if found then
      perform private.block_email((select au.email from auth.users au where au.id = p_user), 'spam');
      delete from public.one_time_keys where user_id = p_user;
    end if;
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- Notification inbox check. The phone registers a random token; a background
-- task later asks, without a login session, how many message envelopes are
-- waiting. The answer is 0 for a wrong token, so it reveals nothing.
-- ---------------------------------------------------------------------------
create or replace function public.set_inbox_token(p_device_key text, p_token text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  if p_token is null or length(p_token) < 32 or length(p_token) > 128 then
    raise exception 'invalid token' using errcode = '22023';
  end if;
  insert into private.inbox_tokens (user_id, token_hash)
  values (v_uid, encode(extensions.digest(p_token, 'sha256'), 'hex'))
  on conflict (user_id) do update set token_hash = excluded.token_hash, updated_at = now();
end
$$;

create or replace function public.inbox_pending(p_user uuid, p_token text)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_user is null or p_token is null or length(p_token) < 32 or length(p_token) > 128 then
    return 0;
  end if;
  if not exists (
    select 1 from private.inbox_tokens t
     where t.user_id = p_user
       and t.token_hash = encode(extensions.digest(p_token, 'sha256'), 'hex')
  ) then
    return 0;
  end if;
  return (
    select least(count(*), 99)::integer
      from public.relay r
     where r.recipient_id = p_user and r.type = 'message' and r.expires_at > now()
  );
end
$$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------
revoke all on function public.change_username(text, text) from public, anon;
revoke all on function public.block_user(text, uuid) from public, anon;
revoke all on function public.unblock_user(text, uuid) from public, anon;
revoke all on function public.my_blocks() from public, anon;
revoke all on function public.report_spam(text, uuid) from public, anon;
revoke all on function public.set_inbox_token(text, text) from public, anon;
revoke all on function public.inbox_pending(uuid, text) from public;

grant execute on function public.change_username(text, text) to authenticated;
grant execute on function public.block_user(text, uuid) to authenticated;
grant execute on function public.unblock_user(text, uuid) to authenticated;
grant execute on function public.my_blocks() to authenticated;
grant execute on function public.report_spam(text, uuid) to authenticated;
grant execute on function public.set_inbox_token(text, text) to authenticated;
grant execute on function public.inbox_pending(uuid, text) to anon, authenticated;

-- >>>>>>>>>> 20261116000000_bvm_v3_account_backup.sql >>>>>>>>>>
-- =============================================================================
-- BVM v3: password-protected account backup. Apply after the v1 and v2
-- migrations (SQL editor: paste and run). Safe to re-run.
--
-- Lets a new (or reinstalled) phone keep the user's app passwords and
-- contact list. The phone encrypts the backup itself (AES-256-GCM, key from
-- Argon2id of the app password); the server stores two opaque copies:
-- one opens with the main password, the other with the secondary password or,
-- when there is none, with a random key nobody knows. Both copies always
-- exist and have the same size, so the server cannot tell whether a
-- secondary password exists. No messages are ever in the backup.
-- =============================================================================

create table if not exists private.account_backups (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  copy_a     text not null,
  copy_b     text not null,
  updated_at timestamptz not null default now(),
  constraint account_backups_size check (octet_length(copy_a) <= 262144 and octet_length(copy_b) <= 262144)
);
alter table private.account_backups enable row level security;

-- Only the account's current phone may replace the backup.
create or replace function public.put_account_backup(p_device_key text, p_copy_a text, p_copy_b text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  if p_copy_a is null or p_copy_b is null or length(p_copy_a) < 64 or length(p_copy_b) < 64 then
    raise exception 'invalid backup' using errcode = '22023';
  end if;
  insert into private.account_backups (user_id, copy_a, copy_b)
  values (v_uid, p_copy_a, p_copy_b)
  on conflict (user_id) do update
    set copy_a = excluded.copy_a, copy_b = excluded.copy_b, updated_at = now();
end
$$;

-- A phone that just signed in with the e-mail code reads the backup before it
-- registers its own keys, so this needs no device key.
create or replace function public.get_account_backup()
returns table (copy_a text, copy_b text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  return query
    select b.copy_a, b.copy_b from private.account_backups b where b.user_id = auth.uid();
end
$$;

revoke all on function public.put_account_backup(text, text, text) from public, anon;
revoke all on function public.get_account_backup() from public, anon;
grant execute on function public.put_account_backup(text, text, text) to authenticated;
grant execute on function public.get_account_backup() to authenticated;

-- >>>>>>>>>> 20261118000000_bvm_v4_rate_limits.sql >>>>>>>>>>
-- =============================================================================
-- BVM v4: per-account rate limits. Apply after v1-v3 (SQL editor: paste and
-- run). Safe to re-run.
--
-- Slows down username enumeration, one-time-key exhaustion, relay flooding,
-- report abuse and backup churn. The limits are far above normal use; a
-- client over a limit gets SQLSTATE BVM05 and retries later (queued messages
-- stay in the phone's outbox).
--
--   action             limit         used by
--   lookup             200 / hour    lookup_user, username_available
--   claim              200 / hour    claim_one_time_key (all targets)
--   claim:<user id>     20 / hour    claim_one_time_key (one target)
--   send              3000 / hour    relay_send (a photo is ~10 parts)
--   report              20 / day     report_spam
--   backup              60 / hour    put_account_backup
--
-- The counters hold only a user id, an action name and a count; rows older
-- than two days are purged daily and all rows go with the account.
-- =============================================================================

create table if not exists private.rate_limits (
  user_id      uuid not null references auth.users (id) on delete cascade,
  action       text not null,
  window_start timestamptz not null default now(),
  hits         integer not null default 0,
  primary key (user_id, action)
);
alter table private.rate_limits enable row level security;

-- Fixed-window counter. Raises BVM05 once p_limit calls were made within
-- p_window. The failed call's increment is rolled back with it, so a client
-- that keeps retrying does not extend its own block.
create or replace function private.hit_rate_limit(p_uid uuid, p_action text, p_limit integer, p_window interval)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_hits integer;
begin
  if p_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  insert into private.rate_limits as r (user_id, action, window_start, hits)
  values (p_uid, p_action, now(), 1)
  on conflict (user_id, action) do update
    set hits = case when r.window_start < now() - p_window then 1 else r.hits + 1 end,
        window_start = case when r.window_start < now() - p_window then now() else r.window_start end
  returning r.hits into v_hits;
  if v_hits > p_limit then
    raise exception 'too many requests, try again later' using errcode = 'BVM05';
  end if;
end
$$;
revoke all on function private.hit_rate_limit(uuid, text, integer, interval) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Directory lookups (now volatile: they write the counter).
-- ---------------------------------------------------------------------------
create or replace function public.username_available(p_username text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform private.hit_rate_limit(auth.uid(), 'lookup', 200, interval '1 hour');
  if p_username is null or p_username !~ '^[a-z0-9_]{3,24}$' then
    return false;
  end if;
  return not exists (select 1 from public.users u where u.username = p_username);
end
$$;

create or replace function public.lookup_user(p_username text)
returns table (id uuid, username text, identity_key text, signing_key text)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  perform private.hit_rate_limit(auth.uid(), 'lookup', 200, interval '1 hour');
  return query
    select u.id, u.username, u.identity_key, u.signing_key
      from public.users u
     where u.username = lower(trim(p_username))
       and u.suspended_at is null;
end
$$;

-- ---------------------------------------------------------------------------
-- One-time keys: a total and a per-target limit, so one account cannot
-- drain someone's keys (the signed fallback key keeps sessions possible).
-- ---------------------------------------------------------------------------
create or replace function public.claim_one_time_key(p_user_id uuid)
returns table (key_id text, public_key text, signature text, is_fallback boolean)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_row public.one_time_keys%rowtype;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_user_id = auth.uid() then
    raise exception 'cannot claim your own keys' using errcode = '22023';
  end if;
  perform private.assert_not_suspended(auth.uid());
  perform private.hit_rate_limit(auth.uid(), 'claim', 200, interval '1 hour');
  perform private.hit_rate_limit(auth.uid(), 'claim:' || p_user_id::text, 20, interval '1 hour');

  delete from public.one_time_keys k
   where k.id = (
     select k2.id from public.one_time_keys k2
      where k2.user_id = p_user_id
      order by k2.id
      limit 1
      for update skip locked
   )
  returning k.* into v_row;

  if v_row.id is not null then
    return query select v_row.key_id, v_row.public_key, v_row.signature, false;
    return;
  end if;

  return query
    select u.fallback_key->>'id', u.fallback_key->>'key', u.fallback_key->>'sig', true
      from public.users u
     where u.id = p_user_id and u.fallback_key is not null;
end
$$;

-- ---------------------------------------------------------------------------
-- Relay
-- ---------------------------------------------------------------------------
create or replace function public.relay_send(
  p_device_key text,
  p_id         uuid,
  p_recipient  uuid,
  p_type       text,
  p_ciphertext text,
  p_expires_at timestamptz default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  perform private.assert_not_suspended(v_uid);
  if p_id is null or p_recipient is null then
    raise exception 'missing id or recipient' using errcode = '22023';
  end if;
  perform private.hit_rate_limit(v_uid, 'send', 3000, interval '1 hour');
  if exists (select 1 from private.blocks b where b.blocker_id = p_recipient and b.blocked_id = v_uid) then
    return;
  end if;
  insert into public.relay (id, recipient_id, sender_id, type, ciphertext, expires_at)
  values (p_id, p_recipient, v_uid, p_type, p_ciphertext, p_expires_at)
  on conflict (id) do nothing;
end
$$;

-- ---------------------------------------------------------------------------
-- Spam reports
-- ---------------------------------------------------------------------------
create or replace function public.report_spam(p_device_key text, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := auth.uid();
  v_reports integer;
begin
  perform private.assert_current_device(v_uid, p_device_key);
  perform private.hit_rate_limit(v_uid, 'report', 20, interval '1 day');
  perform public.block_user(p_device_key, p_user);
  insert into private.spam_reports (reporter_id, reported_id)
  select v_uid, p_user where exists (select 1 from auth.users au where au.id = p_user)
  on conflict (reporter_id, reported_id) do update set created_at = now();

  select count(*) into v_reports
    from private.spam_reports s
    join public.users reporter on reporter.id = s.reporter_id
   where s.reported_id = p_user
     and s.created_at > now() - interval '30 days'
     and reporter.created_at < now() - interval '1 day';

  if v_reports >= 5 then
    update public.users set suspended_at = now()
     where id = p_user and suspended_at is null;
    if found then
      perform private.block_email((select au.email from auth.users au where au.id = p_user), 'spam');
      delete from public.one_time_keys where user_id = p_user;
    end if;
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- Account backup
-- ---------------------------------------------------------------------------
create or replace function public.put_account_backup(p_device_key text, p_copy_a text, p_copy_b text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  perform private.hit_rate_limit(v_uid, 'backup', 60, interval '1 hour');
  if p_copy_a is null or p_copy_b is null or length(p_copy_a) < 64 or length(p_copy_b) < 64 then
    raise exception 'invalid backup' using errcode = '22023';
  end if;
  insert into private.account_backups (user_id, copy_a, copy_b)
  values (v_uid, p_copy_a, p_copy_b)
  on conflict (user_id) do update
    set copy_a = excluded.copy_a, copy_b = excluded.copy_b, updated_at = now();
end
$$;

-- ---------------------------------------------------------------------------
-- Daily purge of old counters.
-- ---------------------------------------------------------------------------
select cron.schedule(
  'bvm-rate-limit-purge',
  '17 3 * * *',
  $$delete from private.rate_limits where window_start < now() - interval '2 days'$$
);

-- >>>>>>>>>> 20261119000000_bvm_v5_inbox_quota.sql >>>>>>>>>>
-- =============================================================================
-- BVM v5: bounded server storage for undelivered messages. Apply after v1-v4
-- (SQL editor: paste and run). Safe to re-run.
--
-- When a recipient does not open the app, envelopes wait on the server. To
-- keep that bounded:
--
--   * Inbox quota: at most 10 MB of waiting messages/photos per recipient and
--     3 MB from any one sender to one recipient. Over the quota relay_send
--     fails with SQLSTATE BVM06; the sender's phone keeps the message in its
--     own outbox and retries later, so nothing is lost and the waiting data
--     sits on the sender's phone instead of the server.
--   * Small control envelopes (receipts) expire after 3 days; text after
--     30 days and photo parts after 7 days as before (photos: set by the app).
--   * Envelopes for accounts whose phone has not fetched for 30 days are
--     purged, together with the TTL job.
--
-- Control envelopes ('delete', 'timer_change') are tiny and exempt from the
-- quota so a wipe or delete command always gets through (they are still rate
-- limited by v4).
-- =============================================================================

alter table public.users add column if not exists last_fetch_at timestamptz;

create or replace function private.assert_inbox_space(p_sender uuid, p_recipient uuid, p_bytes integer)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_total bigint;
  v_pair  bigint;
begin
  select coalesce(sum(octet_length(r.ciphertext)), 0),
         coalesce(sum(octet_length(r.ciphertext)) filter (where r.sender_id = p_sender), 0)
    into v_total, v_pair
    from public.relay r
   where r.recipient_id = p_recipient and r.type = 'message';
  if v_total + p_bytes > 10485760 or v_pair + p_bytes > 3145728 then
    raise exception 'the recipient''s inbox is full, try again later' using errcode = 'BVM06';
  end if;
end
$$;
revoke all on function private.assert_inbox_space(uuid, uuid, integer) from public, anon, authenticated;

-- Receipts live 3 days at most; everything else keeps the v1 clamp.
create or replace function private.relay_before_insert()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_max interval := case when new.type = 'receipt' then interval '3 days' else interval '30 days' end;
begin
  new.created_at := now();
  if new.expires_at is null or new.expires_at > now() + v_max then
    new.expires_at := now() + v_max;
  elsif new.expires_at < now() + interval '1 minute' then
    new.expires_at := now() + interval '1 minute';
  end if;
  return new;
end
$$;
revoke all on function private.relay_before_insert() from public, anon, authenticated;

create or replace function public.relay_send(
  p_device_key text,
  p_id         uuid,
  p_recipient  uuid,
  p_type       text,
  p_ciphertext text,
  p_expires_at timestamptz default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  perform private.assert_not_suspended(v_uid);
  if p_id is null or p_recipient is null then
    raise exception 'missing id or recipient' using errcode = '22023';
  end if;
  perform private.hit_rate_limit(v_uid, 'send', 3000, interval '1 hour');
  if exists (select 1 from private.blocks b where b.blocker_id = p_recipient and b.blocked_id = v_uid) then
    return;
  end if;
  -- A retry of an envelope that is already stored is a no-op, not a quota hit.
  if exists (select 1 from public.relay r where r.id = p_id) then
    return;
  end if;
  if p_type = 'message' then
    perform private.assert_inbox_space(v_uid, p_recipient, octet_length(coalesce(p_ciphertext, '')));
  end if;
  insert into public.relay (id, recipient_id, sender_id, type, ciphertext, expires_at)
  values (p_id, p_recipient, v_uid, p_type, p_ciphertext, p_expires_at)
  on conflict (id) do nothing;
end
$$;

-- Same as v1, plus the last-fetch time used by the inactive-inbox purge.
create or replace function public.relay_fetch(p_device_key text, p_limit integer default 100)
returns table (id uuid, sender_id uuid, type text, ciphertext text)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_uid uuid := auth.uid();
begin
  perform private.assert_current_device(v_uid, p_device_key);
  update public.users u set last_fetch_at = now()
   where u.id = v_uid and (u.last_fetch_at is null or u.last_fetch_at < now() - interval '1 hour');
  return query
    select r.id, r.sender_id, r.type, r.ciphertext
      from public.relay r
     where r.recipient_id = v_uid and r.expires_at > now()
     order by r.created_at, r.id
     limit least(greatest(coalesce(p_limit, 100), 1), 200);
end
$$;

-- TTL job: expired envelopes, plus everything waiting for a phone that has
-- not fetched for 30 days (accounts that registered before v5 count from
-- their first fetch afterwards).
select cron.schedule(
  'bvm-relay-ttl',
  '*/5 * * * *',
  $$delete from public.relay where expires_at < now()
      or recipient_id in (select u.id from public.users u where u.last_fetch_at < now() - interval '30 days')$$
);
